/**
 * Dataset.js
 * Contains the page contents for the dataset download page.
 * The user should be able to download datasets directly from physio.net
 */

import { Button } from "@mui/material";
import React from "react";
import {BrowserRouter as Router, Switch, Route} from 'react-router-dom';

const datasets = [
  { title: "A Cardiovascular Simulator for Research", link: "" }
]

class Dataset extends React.Component {

  render() {
    return (
      <>
        <h1>Datasets</h1>
        <Button variant="outlined" href={"https://physionet.org/static/published-projects/charisdb/charis-database-1.0.0.zip"}>
          Download
        </Button>
      </>
    )
  }
}

export default Dataset;
